#include <stdio.h>

int main() {
    int a[] = {4, 2, 2, 8, 3, 3, 1};
    int n = 7;
    int counts[9] = {0};
    for (int i = 0; i < n; i++) {
        counts[a[i]]++;
    }
    int k = 0;
    for (int v = 0; v <= 8; v++) {
        while (counts[v] > 0) {
            a[k++] = v;
            counts[v]--;
        }
    }
    for (int i = 0; i < n; i++) printf("%d ", a[i]);
    printf("\n");
    return 0;
}
